// ============================================================================
// FAO Error Handler - Extract Failure
// ----------------------------------------------------------------------------
// FAO-GOV-008: set as errorWorkflow on the flagship only. When a flagship
// execution fails (including a failed Writer or notifier call), this
// workflow receives the flagship's execution id, which fao_run_claim
// recorded on the run. Record Run Failure passes it to fao_run_fail, which
// writes FAILED and moves the run to FAILED (or, after a request exists,
// leaves the request standing for the sweep).
//
// The error message is untrusted text: control characters become spaces
// and it is cut to 500 characters before it reaches the database.
// ============================================================================

const data = (($input.first() || {}).json) || {};
const execution = data.execution && typeof data.execution === 'object' ? data.execution : {};

const id = execution.id;
if (id === undefined || id === null || id === '') {
  throw new Error('FAO-GOV-008 error handler: the error payload has no execution id');
}

const clean = (v, max) => String(v === undefined || v === null ? '' : v)
  .replace(/[\u0000-\u001f\u007f]/g, ' ')
  .slice(0, max);

const err = execution.error && typeof execution.error === 'object' ? execution.error : {};

return [{
  json: {
    n8n_execution_id: id,
    failed_node: clean(execution.lastNodeExecuted, 200),
    message: clean(err.message, 500)
  }
}];
